const $=id=>document.getElementById(id);
const ui={canvas:$('game'),overlay:$('overlay'),score:$('score'),combo:$('combo'),time:$('time'),round:$('round-label'),health:$('player-health'),oppHealth:$('opponent-health'),telegraph:$('telegraph'),pop:$('action-pop'),flash:$('impact-flash'),mode:$('mode-label'),action:$('action-label'),best:$('best-score'),sessions:$('sessions-count'),punches:$('total-punches'),accuracy:$('accuracy'),bestCombo:$('best-combo'),rank:$('rank'),skillStraight:$('skill-straight'),skillDodge:$('skill-dodge'),skillCombo:$('skill-combo'),skillMatch:$('skill-match'),difficulty:$('difficulty'),sensitivity:$('sensitivity'),sensitivityValue:$('sensitivity-value'),camera:$('camera'),cameraBtn:$('camera-btn'),cameraPill:$('camera-pill'),cameraFrame:document.querySelector('.camera-frame'),pose:$('pose-overlay'),tracking:$('tracking-state'),hint:$('camera-hint'),calibrate:$('calibrate-btn'),leftSignal:$('left-signal'),rightSignal:$('right-signal'),leftStatus:$('left-status'),rightStatus:$('right-status'),coach:$('coach-tip'),sound:$('sound-btn'),pause:$('pause-btn')};
const config={easy:{attack:5,windup:1.55,damage:10},normal:{attack:3.7,windup:1.25,damage:14},hard:{attack:2.7,windup:1,damage:18}};
let arena;try{arena=new Arena3D(ui.canvas);}catch(e){console.error('WebGL unavailable',e);ui.canvas.style.background='radial-gradient(circle,#405463,#101820)';ui.coach.textContent='立体画面在当前浏览器不可用，请使用支持 WebGL 2 的浏览器。键盘与体感得分仍可使用。';arena={update(){},playerStrike(){},enemyStrike(){},enemyHit(){},playerHit(){},burst(){},setDefense(){}};}
const emptyRecord=()=>({sessions:0,punches:0,hits:0,straightHits:0,dodges:0,bestCombo:0,bestScore:0,bestRank:'拳馆新秀'});
let record;try{record={...emptyRecord(),...JSON.parse(localStorage.getItem('one-more-round-record')||'{}')};}catch{record=emptyRecord();}
const saveRecord=()=>{try{localStorage.setItem('one-more-round-record',JSON.stringify(record));}catch{}};
let game={state:'ready',round:1,time:30,score:0,combo:0,maxCombo:0,punches:0,hits:0,straightHits:0,dodges:0,health:100,opponent:100,attackIn:3.5,attack:null,stun:0,defense:'neutral',defenseUntil:0,lastPunch:0,hookSide:0};
let soundOn=true,audioCtx=null,popTimer=0,flashTimer=0,lastFrame=performance.now(),stream=null,landmarker=null,tracking=false,lastVideoTime=-1,lastPoseTick=0,cameraPhase='off';
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const detector=new PunchDetector(onCameraPunch,onCameraUpdate);
const rankFor=score=>score>=4200?'拳馆传奇':score>=2900?'金腰带挑战者':score>=1700?'拳馆精英':score>=750?'实力新秀':'拳馆新秀';
function tone(f=480,d=.1,type='triangle',volume=.08){if(!soundOn)return;try{const c=audioCtx||(audioCtx=new AudioContext());const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(90,f*.5),c.currentTime+d);g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+d);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+d);}catch{}}
function pop(text,color='#e5ff31'){ui.pop.textContent=text;ui.pop.style.color=color;ui.pop.classList.remove('show');void ui.pop.offsetWidth;ui.pop.classList.add('show');clearTimeout(popTimer);popTimer=setTimeout(()=>ui.pop.classList.remove('show'),760);}
function flash(color){ui.flash.style.background=color;ui.flash.classList.add('active');clearTimeout(flashTimer);flashTimer=setTimeout(()=>ui.flash.classList.remove('active'),120);}
function hud(){ui.score.textContent=String(game.score).padStart(4,'0');ui.combo.textContent=game.combo;ui.time.textContent=Math.ceil(game.time);ui.health.style.width=game.health+'%';ui.oppHealth.style.width=game.opponent+'%';ui.round.textContent=`第 ${game.round} / 3 回合`;document.querySelectorAll('.round-pips i').forEach((p,i)=>p.classList.toggle('active',i<game.round));}
function refreshRecord(){ui.best.textContent=record.bestScore;ui.sessions.textContent=`${record.sessions} 场训练`;ui.punches.textContent=record.punches;ui.accuracy.textContent=(record.punches?Math.round(record.hits/record.punches*100):0)+'%';ui.bestCombo.textContent=record.bestCombo;ui.rank.textContent=record.bestRank;for(const [element,value,max] of [[ui.skillStraight,record.straightHits,10],[ui.skillDodge,record.dodges,5],[ui.skillCombo,record.bestCombo,10],[ui.skillMatch,record.sessions,3]]){element.style.width=clamp(value/max*100,0,100)+'%';element.parentElement.classList.toggle('complete',value>=max);}}
function showOverlay(kicker,title,description,buttonText,onClick){ui.overlay.innerHTML=`<div class="overlay-content"><span class="overline">${kicker}</span><h2>${title}</h2><p>${description}</p><button id="overlay-button" class="btn btn-primary">${buttonText} <span>↗</span></button><small>摄像头画面只在本机处理；请在安全、宽敞的地方活动。</small></div>`;ui.overlay.classList.remove('hidden');$('overlay-button').onclick=onClick;}
function start(){game={state:'playing',round:1,time:30,score:0,combo:0,maxCombo:0,punches:0,hits:0,straightHits:0,dodges:0,health:100,opponent:100,attackIn:2.5,attack:null,stun:0,defense:'neutral',defenseUntil:0,lastPunch:0,hookSide:0};ui.overlay.classList.add('hidden');ui.action.textContent='观察对手，寻找破绽';ui.coach.textContent='对手准备出拳时会出现红色提示。左右侧闪，或双手抱架来防守。';hud();}
function end(reason){if(game.state==='over')return;game.state='over';game.attack=null;ui.telegraph.classList.remove('show');record.sessions++;record.punches+=game.punches;record.hits+=game.hits;record.straightHits+=game.straightHits;record.dodges+=game.dodges;record.bestCombo=Math.max(record.bestCombo,game.maxCombo);record.bestScore=Math.max(record.bestScore,game.score);if(game.score>=(record.rankScore||0)){record.rankScore=game.score;record.bestRank=rankFor(game.score);}saveRecord();refreshRecord();const accuracy=game.punches?Math.round(game.hits/game.punches*100):0;const title=reason==='ko'?'漂亮的终结！':reason==='lost'?'别停下，继续练。':'回合结束！';showOverlay('TRAINING COMPLETE',title,`段位：<b style="color:#e5ff31">${rankFor(game.score)}</b><br>得分 ${game.score} · 命中率 ${accuracy}% · 最佳连击 ${game.maxCombo}`, '再战一场',start);tone(reason==='lost'?230:670,.38,'triangle');}
function roundBreak(){game.state='break';ui.telegraph.classList.remove('show');showOverlay(`ROUND ${game.round} CLEAR`,'喝口水，再来一回合。',`当前得分 ${game.score} · 命中 ${game.hits} 拳 · 生命 ${game.health}%`,'下一回合',()=>{game.round++;game.time=30;game.attackIn=2.5;game.attack=null;game.state='playing';ui.overlay.classList.add('hidden');hud();});tone(580,.2);}
function punch(side,type='straight',quality=1){const t=performance.now();if(game.state!=='playing'||t-game.lastPunch<170)return;game.lastPunch=t;game.punches++;arena.playerStrike(side,type);const label=type==='straight'?(side===0?'左直拳':'右直拳'):type==='hook'?'摆拳':'勾拳';ui.action.textContent=`${label} · 已出拳`;
  const opponentGuard=game.attack===null&&Math.sin(t*.0018)> .65&&game.stun<=0;
  const blocked=opponentGuard&&type==='straight';
  if(blocked){game.combo=0;game.score+=20;pop('对手抱架 +20','#c7d4ce');tone(230,.08,'square');ui.coach.textContent='直拳被挡！试试摆拳或勾拳，或者等对手出拳时反击。';}
  else{game.hits++;game.combo++;game.maxCombo=Math.max(game.maxCombo,game.combo);const bonus=type==='uppercut'?1.35:type==='hook'?1.2:1;const points=Math.round((90+Math.min(game.combo,15)*12)*bonus*quality);game.score+=points;game.opponent=clamp(game.opponent-(type==='uppercut'?8:type==='hook'?6:5)*quality,0,100);if(type==='straight')game.straightHits++;arena.enemyHit(side,type);pop(`${label} +${points}`);flash('#dfff2544');tone(type==='uppercut'?420:320,.14,'sawtooth',.11);
    if(game.combo%10===0){game.score+=500;game.opponent=clamp(game.opponent-16,0,100);game.stun=2.5;game.attack=null;ui.telegraph.classList.remove('show');arena.burst();pop('火力全开！ +500','#f8ff55');flash('#eaff5d88');tone(940,.42,'triangle',.14);ui.coach.textContent='10 连击！对手短暂眩晕，继续进攻！';}
    if(game.opponent<=0){hud();end('ko');return;}
  }hud();}
function defend(action){if(game.state!=='playing')return;game.defense=action;game.defenseUntil=performance.now()+800;arena.setDefense(action);ui.action.textContent=action==='dodgeLeft'?'左侧闪':action==='dodgeRight'?'右侧闪':action==='duck'?'下潜': '抱架防守';}
function beginAttack(){const cfg=config[ui.difficulty.value]||config.normal;const side=Math.random()<.5?0:1;const body=Math.random()<.24;game.attack={side,body,time:cfg.windup};ui.telegraph.textContent=body?'↓ 身体拳 · 抱架或后撤':side===0?'← 左侧来拳 · 右闪 / 抱架':'右侧来拳 → · 左闪 / 抱架';ui.telegraph.classList.add('show');ui.coach.textContent='红色提示出现时做动作：向安全侧闪避，或双拳举至脸颊前抱架。';}
function resolveAttack(){const a=game.attack;if(!a)return;const cfg=config[ui.difficulty.value]||config.normal;arena.enemyStrike(a.side);const defense=game.defense;const safe=a.side===0?'dodgeRight':'dodgeLeft';const dodged=defense===safe||defense==='duck'&&!a.body;const blocked=defense==='block'||a.body&&defense==='duck';if(dodged){game.score+=120;game.dodges++;game.combo++;game.maxCombo=Math.max(game.maxCombo,game.combo);pop('完美闪避 +120');tone(720,.12);ui.action.textContent='漂亮的闪避！';}else if(blocked){game.score+=50;game.health=clamp(game.health-3,0,100);pop('抱架防守 +50','#c5e6ee');tone(280,.08);ui.action.textContent='挡住了！';}else{game.health=clamp(game.health-cfg.damage,0,100);game.combo=0;arena.playerHit();flash('#ff4f4f');pop('被击中！','#ff9793');tone(160,.22,'sawtooth');ui.action.textContent='被击中，重新抱架';}game.attack=null;game.attackIn=cfg.attack*(.75+Math.random()*.5);ui.telegraph.classList.remove('show');hud();if(game.health<=0)end('lost');}
function pause(){if(game.state==='playing'){game.state='paused';showOverlay('PAUSED','回合暂停','调整站位、喝口水，准备好再继续。','继续比赛',()=>{game.state='playing';ui.overlay.classList.add('hidden');});}else if(game.state==='paused')$('overlay-button')?.click();}
function tick(ts){const dt=clamp((ts-lastFrame)/1000,0,.05);lastFrame=ts;if(game.state==='playing'){
  game.time=Math.max(0,game.time-dt);game.stun=Math.max(0,game.stun-dt);
  if(performance.now()>game.defenseUntil&&game.defense!=='neutral'){game.defense='neutral';arena.setDefense('neutral');}
  if(game.attack){game.attack.time-=dt;if(game.attack.time<=0)resolveAttack();}else if(game.stun<=0){game.attackIn-=dt;if(game.attackIn<=0)beginAttack();}
  if(game.time<=0){if(game.round===3)end('time');else roundBreak();}hud();
}arena.update(dt,game);requestAnimationFrame(tick);}requestAnimationFrame(tick);

function onCameraPunch(event){const label=event.type==='straight'?'直拳':event.type==='hook'?'摆拳':'勾拳';const side=event.side===0?'左':'右';ui[event.side===0?'leftStatus':'rightStatus'].textContent=`${side}${label}`;ui.hint.textContent=`识别到 ${side}${label}。手收回抱架后，可再次出拳。`;if(game.state==='playing')punch(event.side,event.type,event.quality);else pop(`识别到 ${side}${label}`);}
function onCameraUpdate(v){const enteringReady=v.state==='ready'&&cameraPhase!=='ready';cameraPhase=v.state;ui.leftSignal.style.width=Math.round((v.left||0)*100)+'%';ui.rightSignal.style.width=Math.round((v.right||0)*100)+'%';if(v.state==='calibrating'){ui.tracking.textContent=`抱架校准 ${Math.round((v.progress||0)*100)}%`;ui.hint.textContent='双拳放在脸颊前，保持上半身和两只手都在镜头内，约 2 秒。';}else if(v.state==='ready'){ui.tracking.textContent='动作识别中';if(enteringReady)ui.hint.textContent='校准完成。快速出拳后收回抱架；下方信号条会随动作变化。';if(ui.leftStatus.textContent==='待机')ui.leftStatus.textContent='已校准';if(ui.rightStatus.textContent==='待机')ui.rightStatus.textContent='已校准';if(v.defense!=='neutral'&&game.state==='playing'){const map={left:'dodgeLeft',right:'dodgeRight',duck:'duck',block:'block'};defend(map[v.defense]);}}else if(v.state==='reposition'){ui.tracking.textContent='请双手入镜';ui.hint.textContent='镜头需要同时看到头部、双肩、双肘与双手。';}}
async function enableCamera(){if(stream){disableCamera();return;}ui.cameraBtn.disabled=true;ui.tracking.textContent='连接摄像头';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('浏览器不支持摄像头接口');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480},frameRate:{ideal:24,max:30}},audio:false});ui.camera.srcObject=stream;await ui.camera.play();ui.cameraFrame.classList.add('active');ui.cameraPill.textContent='● 摄像头已连接';ui.cameraPill.classList.add('active');ui.cameraBtn.textContent='关闭体感';ui.mode.textContent='摄像头体感模式';ui.tracking.textContent='加载模型';const vision=await import('./vendor/mediapipe/vision_bundle.mjs');const files=await vision.FilesetResolver.forVisionTasks(new URL('./vendor/mediapipe/wasm',import.meta.url).href);const opts={baseOptions:{modelAssetPath:new URL('./vendor/mediapipe/pose_landmarker_lite.task',import.meta.url).href,delegate:'GPU'},runningMode:'VIDEO',numPoses:1,minPoseDetectionConfidence:.5,minTrackingConfidence:.5};try{landmarker=await vision.PoseLandmarker.createFromOptions(files,opts);}catch{opts.baseOptions.delegate='CPU';landmarker=await vision.PoseLandmarker.createFromOptions(files,opts);}tracking=true;detector.calibrate();ui.calibrate.disabled=false;requestAnimationFrame(trackPose);}catch(e){console.warn('Camera:',e);const reason=e.name==='NotAllowedError'?'请允许浏览器使用摄像头。':e.message||'摄像头或模型启动失败';disableCamera();ui.tracking.textContent='启动失败';ui.hint.textContent=`${reason} 可继续使用键盘或触屏。`;}finally{ui.cameraBtn.disabled=false;}}
function disableCamera(){tracking=false;landmarker?.close();landmarker=null;stream?.getTracks().forEach(t=>t.stop());stream=null;ui.camera.srcObject=null;ui.cameraFrame.classList.remove('active');ui.cameraPill.textContent='● 未连接摄像头';ui.cameraPill.classList.remove('active');ui.cameraBtn.textContent='开启体感';ui.mode.textContent='键盘 / 触屏模式';ui.calibrate.disabled=true;ui.leftSignal.style.width='0';ui.rightSignal.style.width='0';ui.leftStatus.textContent='待机';ui.rightStatus.textContent='待机';ui.pose.getContext('2d').clearRect(0,0,ui.pose.width,ui.pose.height);detector.reset();cameraPhase='off';}
function trackPose(ts){if(!tracking||!landmarker)return;if(ts-lastPoseTick>55&&ui.camera.readyState>=2&&ui.camera.currentTime!==lastVideoTime){lastPoseTick=ts;lastVideoTime=ui.camera.currentTime;try{const result=landmarker.detectForVideo(ui.camera,ts);const p=result.landmarks?.[0];if(p){detector.process(p,result.worldLandmarks?.[0],ts);drawPose(p);}else{ui.tracking.textContent='请站入画面';ui.pose.getContext('2d').clearRect(0,0,ui.pose.width,ui.pose.height);}}catch(e){console.warn('Pose frame:',e);}}requestAnimationFrame(trackPose);}
function drawPose(p){const c=ui.pose,w=ui.camera.videoWidth,h=ui.camera.videoHeight;if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const g=c.getContext('2d');g.clearRect(0,0,w,h);g.strokeStyle='#e5ff31';g.lineWidth=3;for(const [a,b] of [[11,12],[11,13],[13,15],[12,14],[14,16]]){g.beginPath();g.moveTo(p[a].x*w,p[a].y*h);g.lineTo(p[b].x*w,p[b].y*h);g.stroke();}for(const i of [0,11,12,13,14,15,16]){g.fillStyle=i>=15?'#ff7b66':'#e5ff31';g.beginPath();g.arc(p[i].x*w,p[i].y*h,i>=15?7:4,0,Math.PI*2);g.fill();}}

ui.cameraBtn.onclick=enableCamera;ui.calibrate.onclick=()=>{if(tracking){detector.calibrate();ui.leftStatus.textContent='待机';ui.rightStatus.textContent='待机';}};ui.sensitivity.oninput=()=>{ui.sensitivityValue.textContent=ui.sensitivity.value;detector.setSensitivity(ui.sensitivity.value);};ui.sound.onclick=()=>{soundOn=!soundOn;ui.sound.textContent=soundOn?'♪':'♪̸';ui.sound.setAttribute('aria-label',soundOn?'关闭音效':'开启音效');};ui.pause.onclick=pause;$('start-btn').onclick=start;
const actions={KeyJ:()=>punch(0),KeyL:()=>punch(1),KeyK:()=>{game.hookSide=1-game.hookSide;punch(game.hookSide,'hook');},KeyA:()=>defend('dodgeLeft'),KeyD:()=>defend('dodgeRight'),KeyS:()=>defend('block'),Space:pause};document.addEventListener('keydown',e=>{if(actions[e.code]){e.preventDefault();if(!e.repeat)actions[e.code]();}});
const touch={jab:()=>punch(0),cross:()=>punch(1),hook:()=>{game.hookSide=1-game.hookSide;punch(game.hookSide,'hook');},dodgeLeft:()=>defend('dodgeLeft'),dodgeRight:()=>defend('dodgeRight'),block:()=>defend('block')};document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();touch[b.dataset.action]?.();}));
